def resolve(ev):
    out = []
    for item in ev.split():
        mod, fn = item.split(":")
        if mod not in MOD: out.append(item); continue
        path = CHK / MOD[mod] / "🦀️.rs"
        hits = [i for i, line in enumerate(path.read_text(encoding="utf-8").splitlines(), 1) if re.search(rf"\bfn {re.escape(fn)}\b", line)]
        out.append(f"{path.relative_to(CHK)}:{hits[0]}" if hits else f"{item} (not found)")
    return "; ".join(out)

def ex_text(r):
    if r["ex"] is None: return ""
    return repr(float(r["ex"])) if r["kind"] == "n" else str(r["ex"])

if __name__ == "__main__":
    out = ["# key|scope|kind|unit|example|flags|en|de|confidence|note   (EN 1992: hand-reviewed stored units, see catalogue-bridge-en1992-units.py and audits/wave2/units-review-en1992.md; this file is generated by that script)"]
    for r in ROWS:
        kind = r["kind"] if r["kind"] != "c" else "c"
        out.append("|".join([r["key"], r["scope"], kind, r["unit"], ex_text(r), r["flags"], r["en"], r["de"], r["conf"], r["ev"].replace("|", "/")]))
    for key, value, en, de in CHOICES:
        out.append(f"@choice {key}|{value}|{en}|{de}")
    (HERE / "catalogue-bridge-en1992-inputs.tsv").write_text("\n".join(out) + "\n", encoding="utf-8")
    print(len(ROWS), "rows", len(CHOICES), "choices")
